export const ADMIN_EMAIL = "gerito.diseno@gmail.com";

export const isUserAuthorized = async (email: string): Promise<boolean> => {
  if (email === ADMIN_EMAIL) return true;
  const docRef = doc(db, "authorized_users", email.toLowerCase());
  const docSnap = await getDoc(docRef);
  return docSnap.exists();
};

export const addAuthorizedUser = async (email: string) => {
  const emailLower = email.toLowerCase();
  await setDoc(doc(db, "authorized_users", emailLower), {
    email: emailLower,
    addedAt: Date.now()
  });
};

export const removeAuthorizedUser = async (email: string) => {
  await deleteDoc(doc(db, "authorized_users", email.toLowerCase()));
};

import { EmailFormData } from '../types';

/**
 * Note: Direct calls to SendGrid from browser will fail due to CORS.
 * In a real Vercel environment, you would use a Serverless Function (/api/send-email).
 * This service simulates the request structure required.
 */
export const sendEmailViaSendGrid = async (data: EmailFormData, apiKey: string) => {
  const dynamicData = JSON.parse(data.dynamicTemplateData || '{}');

  const payload = {
    personalizations: [
      {
        to: [{ email: data.toEmail }],
        dynamic_template_data: dynamicData,
      },
    ],
    from: {
      email: data.fromEmail,
      name: data.fromName || 'UKUEPA Support',
    },
    template_id: data.templateId,
  };

  try {
    const response = await fetch('https://api.sendgrid.com/v3/mail/send', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(payload),
      mode: 'cors' // This usually triggers CORS preflight error in browser
    });

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.errors?.[0]?.message || 'Failed to send email');
    }

    return { success: true };
  } catch (error: any) {
    console.error('SendGrid Error:', error);
    // If it's a CORS issue, we inform the user to use a proxy or check their settings
    if (error.message.includes('Failed to fetch')) {
        throw new Error("CORS Error: Standard browsers block direct SendGrid API calls for security. Please deploy this to Vercel and use an API route, or use a CORS proxy for development.");
    }
    throw error;
  }
};

import React from 'react';
import { UserProfile } from '../types';
import { auth } from '../firebase';
import { signOut } from 'firebase/auth';

