import React, { useState, useEffect } from 'react';
import { db, addAuthorizedUser, removeAuthorizedUser } from '../firebase';
import { collection, onSnapshot, query, orderBy } from 'firebase/firestore';
import { AuthorizedUser } from '../types';

const AdminPanel: React.FC = () => {
  const [users, setUsers] = useState<AuthorizedUser[]>([]);
  const [newEmail, setNewEmail] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    const q = query(collection(db, 'authorized_users'), orderBy('addedAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const userList: AuthorizedUser[] = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      } as AuthorizedUser));
      setUsers(userList);
    });
    return () => unsubscribe();
  }, []);

  const handleAddUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEmail || !newEmail.includes('@')) {
      setError('Please enter a valid email address');
      return;
    }

    setIsLoading(true);
    setError('');
    try {
      await addAuthorizedUser(newEmail.trim());
      setNewEmail('');
    } catch (err: any) {
      setError('Failed to add user: ' + err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDeleteUser = async (email: string) => {
    if (!window.confirm(`Remove access for ${email}?`)) return;
    try {
      await removeAuthorizedUser(email);
    } catch (err: any) {
      alert('Error: ' + err.message);
    }
  };

  return (
    <div className="space-y-6 max-w-4xl mx-auto">
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
        <h2 className="text-xl font-bold text-slate-800 mb-4 flex items-center">
          <i className="fas fa-user-shield text-blue-600 mr-2"></i>
          Authorized Users
        </h2>
        <p className="text-sm text-slate-500 mb-6">
          Only the emails listed below (plus the admin) will be able to log in to the application using Google OAuth.
        </p>

        <form onSubmit={handleAddUser} className="flex flex-col sm:flex-row gap-3">
          <div className="flex-1 relative">
            <input
              type="email"
              value={newEmail}
              onChange={(e) => setNewEmail(e.target.value)}
              placeholder="user@example.com"
              className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all text-sm"
              disabled={isLoading}
            />
            <i className="fas fa-envelope absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"></i>
          </div>
          <button
            type="submit"
            disabled={isLoading || !newEmail}
            className="px-6 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-semibold transition-colors disabled:opacity-50 flex items-center justify-center min-w-[120px]"
          >
            {isLoading ? <i className="fas fa-spinner fa-spin mr-2"></i> : <i className="fas fa-plus mr-2"></i>}
            Authorize
          </button>
        </form>
        {error && <p className="mt-2 text-xs text-red-500 font-medium">{error}</p>}
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <table className="min-w-full divide-y divide-slate-200">
          <thead className="bg-slate-50">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">Authorized Email</th>
              <th className="px-6 py-3 text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">Date Added</th>
              <th className="px-6 py-3 text-right text-xs font-semibold text-slate-500 uppercase tracking-wider">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200">
            {users.length === 0 ? (
              <tr>
                <td colSpan={3} className="px-6 py-10 text-center text-slate-400 text-sm">
                  No additional authorized users yet.
                </td>
              </tr>
            ) : (
              users.map((user) => (
                <tr key={user.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span className="text-sm font-medium text-slate-700">{user.email}</span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span className="text-xs text-slate-500">{new Date(user.addedAt).toLocaleDateString()}</span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right">
                    <button
                      onClick={() => handleDeleteUser(user.email)}
                      className="text-slate-300 hover:text-red-500 transition-colors p-2"
                    >
                      <i className="fas fa-trash-alt"></i>
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default AdminPanel;

import React, { useState } from 'react';
import { EmailFormData } from '../types';
import { sendEmailViaSendGrid } from '../services/sendgridService';

const EmailForm: React.FC = () => {
  const [formData, setFormData] = useState<EmailFormData>({
    fromEmail: 'noreply@ukuepa.com',
    fromName: 'UKUEPA Team',
    toEmail: '',
    templateId: '',
    dynamicTemplateData: '{\n  "name": "User",\n  "content": "Your message here"\n}',
  });
  const [apiKey, setApiKey] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [status, setStatus] = useState<{ type: 'success' | 'error' | ''; message: string }>({ type: '', message: '' });

  const validateEmail = (email: string) => email.toLowerCase().endsWith('@ukuepa.com');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateEmail(formData.fromEmail)) {
      setStatus({ type: 'error', message: 'Sender email must be a valid @ukuepa.com address.' });
      return;
    }
    if (!apiKey) {
      setStatus({ type: 'error', message: 'SendGrid API Key is required.' });
      return;
    }

    setIsSending(true);
    setStatus({ type: '', message: '' });

    try {
      await sendEmailViaSendGrid(formData, apiKey);
      setStatus({ type: 'success', message: 'Email sent successfully!' });
      setFormData({ ...formData, toEmail: '' });
    } catch (error: any) {
      setStatus({ type: 'error', message: error.message });
    } finally {
      setIsSending(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 max-w-6xl mx-auto">
      <div className="lg:col-span-7 space-y-6">
        <form onSubmit={handleSubmit} className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="bg-slate-50 border-b border-slate-200 px-6 py-4">
            <h2 className="text-lg font-bold text-slate-800 flex items-center">
              <i className="fas fa-paper-plane text-blue-600 mr-2"></i>
              Compose Email
            </h2>
          </div>

          <div className="p-6 space-y-5">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Sender Name</label>
                <input
                  type="text"
                  required
                  value={formData.fromName}
                  onChange={(e) => setFormData({ ...formData, fromName: e.target.value })}
                  placeholder="e.g. UKUEPA Support"
                  className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Sender Email</label>
                <input
                  type="email"
                  required
                  value={formData.fromEmail}
                  onChange={(e) => setFormData({ ...formData, fromEmail: e.target.value })}
                  placeholder="name@ukuepa.com"
                  className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm ${
                    !validateEmail(formData.fromEmail) ? 'border-amber-400 bg-amber-50' : 'border-slate-200'
                  }`}
                />
                {!validateEmail(formData.fromEmail) && (
                  <p className="mt-1 text-[10px] text-amber-600 font-medium italic">Must end in @ukuepa.com</p>
                )}
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Recipient Email</label>
              <input
                type="email"
                required
                value={formData.toEmail}
                onChange={(e) => setFormData({ ...formData, toEmail: e.target.value })}
                placeholder="customer@domain.com"
                className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">SendGrid Template ID</label>
              <input
                type="text"
                required
                value={formData.templateId}
                onChange={(e) => setFormData({ ...formData, templateId: e.target.value })}
                placeholder="d-xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"
                className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm font-mono"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Dynamic Template Data (JSON)</label>
              <textarea
                rows={6}
                value={formData.dynamicTemplateData}
                onChange={(e) => setFormData({ ...formData, dynamicTemplateData: e.target.value })}
                className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm font-mono bg-slate-900 text-green-400"
                placeholder="{ ... }"
              ></textarea>
            </div>

            {status.message && (
              <div className={`p-4 rounded-lg flex items-start space-x-3 ${status.type === 'success' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'}`}>
                <i className={`fas ${status.type === 'success' ? 'fa-check-circle' : 'fa-exclamation-triangle'} mt-1`}></i>
                <span className="text-sm font-medium">{status.message}</span>
              </div>
            )}

            <button
              type="submit"
              disabled={isSending}
              className="w-full py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold transition-all shadow-lg shadow-blue-200 flex items-center justify-center space-x-2 disabled:opacity-50"
            >
              {isSending ? (
                <>
