            Authentication
          </h3>
          <p className="text-xs text-slate-500 mb-4">
            Enter your SendGrid API Key. It is stored in memory and used for requests.
          </p>
          <input
            type="password"
            value={apiKey}
            onChange={(e) => setApiKey(e.target.value)}
            placeholder="SG.xxxxxxxxxxxxxxxxxx"
            className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none text-sm font-mono"
          />
        </div>

        <div className="bg-blue-600 rounded-2xl shadow-lg p-6 text-white">
          <h3 className="text-lg font-bold mb-3">Domain Verified: ukuepa.com</h3>
          <p className="text-xs text-blue-100 leading-relaxed">
            As specified, you can use any valid sender identity under the <span className="font-bold underline">ukuepa.com</span> domain. Ensure the identity is registered in your SendGrid dashboard or that Domain Authentication is active for this domain.
          </p>
          <div className="mt-6 pt-6 border-t border-blue-500/50 flex items-center space-x-4">
            <div className="p-2 bg-blue-500 rounded-lg">
              <i className="fas fa-shield-alt text-xl"></i>
            </div>
            <div>
              <p className="text-[10px] font-bold uppercase tracking-wider text-blue-200">Security Note</p>
              <p className="text-xs">Dynamic templates are handled securely with dynamic JSON data injection.</p>
            </div>
          </div>
        </div>

        <div className="bg-slate-100 rounded-2xl p-6 border border-slate-200">
          <h4 className="text-xs font-bold text-slate-700 mb-3 uppercase">Quick Instructions</h4>
          <ul className="text-xs text-slate-600 space-y-2">
