// api/send-email.ts
import sgMail from '@sendgrid/mail';

export default async function handler(req: any, res: any) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  const apiKey = process.env.SENDGRID_API_KEY;
  if (!apiKey) {
    return res.status(500).json({ error: 'SendGrid API key not configured on server.' });
  }

  try {
    sgMail.setApiKey(apiKey);

    const { toEmail, fromEmail, fromName, templateId, dynamicTemplateData } = req.body;

    const msg = {
      to: toEmail,
      from: {
        email: fromEmail || 'noreply@ukuepa.com',
        name: fromName || 'Uk Mails'
      },
      templateId: templateId,
      dynamicTemplateData: dynamicTemplateData || {},
    };

    await sgMail.send(msg);

    return res.status(200).json({ success: true, message: 'Email sent successfully via Uk Mails' });
  } catch (error: any) {
    console.error('SendGrid Error:', error.response?.body || error);
    return res.status(500).json({ 
      error: 'Error sending email', 
      details: error.response?.body?.errors?.[0]?.message || error.message 
    });
  }
}

