      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(data),
    });

    const result = await response.json();

    if (!response.ok) {
      throw new Error(result.error || result.details || 'Failed to send email');
    }

    return result;
  } catch (error: any) {
    console.error('Service Error:', error);
    throw error;
  }
};

