const AdminPanel: React.FC = () => {
  const [users, setUsers] = useState<any[]>([]);
  const [newEmail, setNewEmail] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    // Escuchando la colección correcta según la imagen
    const q = query(collection(db, 'whitelisted_users'), orderBy('addedAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const userList = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setUsers(userList);
    });
    return () => unsubscribe();
  }, []);

  const handleAddUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEmail || !newEmail.includes('@')) {
      setError('Email no válido');
      return;
    }

    setIsLoading(true);
    setError('');
    try {
      await addAuthorizedUser(newEmail.trim(), auth.currentUser?.email || 'admin');
      setNewEmail('');
    } catch (err: any) {
      setError('Error al añadir: ' + err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDeleteUser = async (email: string) => {
    if (!window.confirm(`¿Quitar acceso a ${email}?`)) return;
    try {
      await removeAuthorizedUser(email);
    } catch (err: any) {
      alert('Error: ' + err.message);
    }
  };

  return (
    <div className="space-y-6 max-w-4xl mx-auto">
      <div className="bg-white rounded-3xl shadow-sm border border-slate-200 p-8 transition-all hover:shadow-md">
