import { onAuthStateChanged, signInWithPopup } from 'firebase/auth';
import { auth, googleProvider, ADMIN_EMAIL, isUserAuthorized } from './firebase';
import { UserProfile } from './types';
import Layout from './components/Layout';
import EmailForm from './components/EmailForm';
import AdminPanel from './components/AdminPanel';
import EmailLogs from './components/EmailLogs';

const App: React.FC = () => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [activeView, setActiveView] = useState<'send' | 'admin' | 'logs'>('send');
  const [unauthorizedError, setUnauthorizedError] = useState(false);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      setLoading(true);
      if (firebaseUser && firebaseUser.email) {
        const email = firebaseUser.email;
        const authorized = await isUserAuthorized(email);

        if (authorized) {
          setUser({
            uid: firebaseUser.uid,
            email: email,
            displayName: firebaseUser.displayName || 'User',
            photoURL: firebaseUser.photoURL || `https://ui-avatars.com/api/?name=${email}`,
            isAdmin: email === ADMIN_EMAIL,
            isAuthorized: true
          });
          setUnauthorizedError(false);
        } else {
          setUser(null);
          setUnauthorizedError(true);
          await auth.signOut();
        }
      } else {
        setUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const handleLogin = async () => {
    try {
      setUnauthorizedError(false);
      await signInWithPopup(auth, googleProvider);
    } catch (error) {
      console.error('Login error:', error);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#F8FAFC]">
        <div className="flex flex-col items-center">
          <div className="w-14 h-14 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-6"></div>
          <p className="text-slate-400 font-bold text-xs uppercase tracking-widest animate-pulse">Autenticando Acceso...</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#F8FAFC] p-4">
        <div className="max-w-md w-full bg-white rounded-[2.5rem] shadow-2xl shadow-indigo-100 overflow-hidden border border-slate-100">
          <div className="bg-indigo-600 p-12 text-center relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16 blur-2xl"></div>
            <div className="inline-flex bg-white/10 p-5 rounded-3xl mb-8 backdrop-blur-sm">
              <i className="fas fa-paper-plane text-white text-4xl"></i>
            </div>
            <h1 className="text-4xl font-black text-white mb-2 tracking-tighter">Uk <span className="opacity-70">Mails</span></h1>
            <p className="text-indigo-100 text-xs font-bold uppercase tracking-widest">Sistema de Gestión de Correo</p>
          </div>
          <div className="p-12">
            <p className="text-center text-slate-500 text-sm mb-10 leading-relaxed font-medium">
              Solo personal autorizado de <span className="text-indigo-600 font-bold">ukuepa.com</span> puede acceder a esta plataforma.
            </p>

            <button
              onClick={handleLogin}
              className="w-full flex items-center justify-center space-x-4 py-4 px-6 bg-slate-50 border border-slate-200 rounded-2xl hover:bg-indigo-50 hover:border-indigo-100 transition-all font-bold text-slate-700 shadow-sm active:scale-95 group"
            >
              <img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" className="w-6 h-6 group-hover:scale-110 transition-transform" alt="Google" />
              <span>Entrar con Google</span>
            </button>

            {unauthorizedError && (
              <div className="mt-8 p-5 bg-rose-50 rounded-2xl border border-rose-100 flex items-start space-x-4 animate-in fade-in slide-in-from-bottom-2">
                <i className="fas fa-shield-xmark text-rose-500 text-xl mt-1"></i>
                <div>
                  <p className="text-[10px] font-black text-rose-700 uppercase tracking-widest">Acceso Denegado</p>
                  <p className="text-xs text-rose-600 font-medium mt-1">Tu email no está autorizado. Contacta al administrador para solicitar acceso.</p>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout 
      user={user} 
      activeView={activeView} 
      onNavigate={(view) => setActiveView(view as any)}
    >
      {activeView === 'send' && <EmailForm />}
      {activeView === 'logs' && <EmailLogs />}
      {activeView === 'admin' && <AdminPanel />}
    </Layout>
  );
};

export default App;

import React from 'react';
import { UserProfile } from '../types';
import { auth } from '../firebase';
import { signOut } from 'firebase/auth';

interface LayoutProps {
  children: React.ReactNode;
  user: UserProfile | null;
  onNavigate: (view: 'send' | 'admin' | 'logs') => void;
  activeView: 'send' | 'admin' | 'logs';
}

const Layout: React.FC<LayoutProps> = ({ children, user, onNavigate, activeView }) => {
  const handleSignOut = () => signOut(auth);

  if (!user) return <>{children}</>;

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center space-x-4">
              <div className="flex-shrink-0 bg-indigo-600 p-2 rounded-xl shadow-lg shadow-indigo-100">
                <i className="fas fa-paper-plane text-white text-lg"></i>
              </div>
              <h1 className="text-xl font-black text-slate-900 tracking-tight">
                Uk <span className="text-indigo-600">Mails</span>
              </h1>

              <nav className="hidden md:flex ml-10 space-x-1">
                <button
                  onClick={() => onNavigate('send')}
                  className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
                    activeView === 'send' 
                    ? 'bg-indigo-50 text-indigo-700' 
                    : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'
                  }`}
                >
                  <i className="fas fa-envelope-open-text mr-2"></i>
                  Enviar
                </button>
                <button
                  onClick={() => onNavigate('logs')}
                  className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
                    activeView === 'logs' 
                    ? 'bg-indigo-50 text-indigo-700' 
                    : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'
                  }`}
                >
                  <i className="fas fa-history mr-2"></i>
                  Historial
                </button>
                {user.isAdmin && (
                  <button
                    onClick={() => onNavigate('admin')}
                    className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
                      activeView === 'admin' 
                      ? 'bg-indigo-50 text-indigo-700' 
                      : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'
                    }`}
                  >
                    <i className="fas fa-users-cog mr-2"></i>
                    Admin
                  </button>
                )}
              </nav>
            </div>

            <div className="flex items-center space-x-4">
              <div className="text-right hidden sm:block">
                <p className="text-xs font-bold text-slate-900">{user.displayName}</p>
                <p className="text-[10px] font-medium text-slate-400">{user.email}</p>
              </div>
              <img 
                src={user.photoURL} 
                alt="Profile" 
                className="w-9 h-9 rounded-full border-2 border-white shadow-sm ring-1 ring-slate-100"
              />
              <button
                onClick={handleSignOut}
                className="w-9 h-9 flex items-center justify-center rounded-lg text-slate-400 hover:text-red-500 hover:bg-red-50 transition-all"
                title="Sign Out"
              >
                <i className="fas fa-power-off"></i>
              </button>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {children}
      </main>

      <footer className="bg-white border-t border-slate-200 py-6">
        <div className="max-w-7xl mx-auto px-4 flex flex-col md:flex-row justify-between items-center space-y-4 md:space-y-0">
          <p className="text-xs font-medium text-slate-400 uppercase tracking-widest">Uk Mails Management System</p>
          <div className="flex space-x-6">
             <span className="text-[10px] font-bold text-indigo-600 bg-indigo-50 px-2 py-1 rounded">DOMAIN: UKUEPA.COM</span>
             <span className="text-[10px] font-bold text-slate-400 px-2 py-1">v2.1.0</span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default Layout;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { collection, onSnapshot, query, orderBy, limit } from 'firebase/firestore';

const EmailLogs: React.FC = () => {
  const [logs, setLogs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const q = query(
      collection(db, 'email_logs'),
      orderBy('timestamp', 'desc'),
      limit(50)
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const logList = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setLogs(logList);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  return (
    <div className="max-w-5xl mx-auto space-y-6">
      <div className="flex justify-between items-end mb-4">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Historial de Envíos</h2>
          <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">Registros de actividad reciente</p>
        </div>
        <div className="text-right">
            <span className="text-[10px] font-black bg-indigo-50 text-indigo-600 px-3 py-1 rounded-full uppercase tracking-tighter">Últimos 50 registros</span>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] shadow-xl shadow-slate-200/50 border border-slate-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-slate-100">
            <thead className="bg-slate-50/50">
              <tr>
                <th className="px-6 py-4 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">Fecha y Hora</th>
                <th className="px-6 py-4 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">Plantilla</th>
                <th className="px-6 py-4 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">Cantidad</th>
                <th className="px-6 py-4 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">Remitente</th>
                <th className="px-6 py-4 text-center text-[10px] font-black text-slate-400 uppercase tracking-widest">Estado</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {loading ? (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center">
                    <i className="fas fa-spinner fa-spin text-indigo-600 text-xl"></i>
                  </td>
                </tr>
              ) : logs.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-slate-400 text-sm font-medium italic">
                    No se han registrado envíos todavía.
                  </td>
                </tr>
              ) : (
                logs.map((log) => (
                  <tr key={log.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-xs font-bold text-slate-700">
                        {new Date(log.timestamp).toLocaleDateString()}
                      </div>
                      <div className="text-[10px] text-slate-400">
                        {new Date(log.timestamp).toLocaleTimeString()}
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="text-xs font-bold text-slate-800">{log.templateName}</span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="text-xs font-black text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-md">
                        {log.count} {log.count === 1 ? 'mail' : 'mails'}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-[10px] font-bold text-slate-500 truncate max-w-[150px]">
                        {log.fromEmail}
                      </div>
                      <div className="text-[9px] text-slate-400 italic">
                        por {log.userEmail.split('@')[0]}
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-center">
                      <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                        log.status === 'success' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' :
                        log.status === 'cancelled' ? 'bg-amber-50 text-amber-700 border-amber-100' :
                        'bg-rose-50 text-rose-700 border-rose-100'
                      }`}>
                        {log.status === 'success' ? 'Enviado' : 
                         log.status === 'cancelled' ? 'Cancelado' : 'Error'}
                      </span>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default EmailLogs;

import React, { useState, useMemo, useRef } from 'react';
import { EmailFormData } from '../types';
import { sendEmailViaSendGrid } from '../services/sendgridService';
import { logEmailOperation, auth } from '../firebase';
import Papa from 'papaparse';

const TEMPLATES = [
  { id: 'd-f3b79f64867c484ea8630777e8412030', name: 'Welcome Email (Ukuepa)', preview: 'Welcome to Ukuepa! We are glad to have you on board.' },
  { id: 'd-7a561993f3c448658826d9c6e3b567a1', name: 'Password Reset', preview: 'A password reset was requested for your account.' },
  { id: 'd-928e7c6b5a4d3c2b1a0e9d8c7b6a5f4', name: 'Course Confirmation', preview: 'Your course registration is confirmed. Start learning now!' },
  { id: 'd-1a2b3c4d5e6f7g8h9i0j1k2l3m4n5o', name: 'Support Notification', preview: 'Our support team has responded to your inquiry.' }
];

const EmailForm: React.FC = () => {
  const [formData, setFormData] = useState<EmailFormData>({
    fromEmail: 'info@ukuepa.com',
    fromName: 'Uk Mails Admin',
    toEmail: '',
    templateId: TEMPLATES[0].id,
    dynamicTemplateData: ''
  });

  // CSV States
  const [csvRecipients, setCsvRecipients] = useState<string[]>([]);
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [rawCsvData, setRawCsvData] = useState<any[]>([]);
  const [selectedColumn, setSelectedColumn] = useState('');

  const [isSending, setIsSending] = useState(false);
  const [cancelRequest, setCancelRequest] = useState(false);
  const [status, setStatus] = useState<{ type: 'success' | 'error' | ''; message: string }>({ type: '', message: '' });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const selectedTemplate = useMemo(() => 
    TEMPLATES.find(t => t.id === formData.templateId) || TEMPLATES[0]
  , [formData.templateId]);

  const validateEmail = (email: string) => email.toLowerCase().endsWith('@ukuepa.com');

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setRawCsvData(results.data);
          setSelectedColumn(headers[0]);
          updateRecipients(results.data, headers[0]);
        }
      },
      error: (error) => {
        setStatus({ type: 'error', message: 'Error al procesar CSV: ' + error.message });
      }
    });
  };

  const updateRecipients = (data: any[], column: string) => {
    const emails = data.map(row => row[column]).filter(email => email && email.includes('@'));
    setCsvRecipients(emails);
    if (emails.length > 0) {
      setFormData(prev => ({ ...prev, toEmail: emails[0] }));
    }
  };

  const onColumnChange = (column: string) => {
    setSelectedColumn(column);
    updateRecipients(rawCsvData, column);
  };

  const clearCsv = () => {
    setCsvRecipients([]);
    setCsvHeaders([]);
    setRawCsvData([]);
    setSelectedColumn('');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateEmail(formData.fromEmail)) {
      setStatus({ type: 'error', message: 'El remitente debe ser @ukuepa.com' });
      return;
    }

    setIsSending(true);
    setCancelRequest(false);
    setStatus({ type: '', message: '' });

    const targets = csvRecipients.length > 0 ? csvRecipients : [formData.toEmail];
    let sentCount = 0;
    let finalStatus: 'success' | 'error' | 'cancelled' = 'success';
    let errorMessage = '';

    try {
      for (const email of targets) {
        if (cancelRequest) {
          finalStatus = 'cancelled';
          break;
        }
        await sendEmailViaSendGrid({ ...formData, toEmail: email });
        sentCount++;
      }

      if (finalStatus === 'cancelled') {
        setStatus({ type: 'error', message: `Envío cancelado. Se enviaron ${sentCount} de ${targets.length}.` });
      } else {
        setStatus({ type: 'success', message: `¡${sentCount} mail(s) enviado(s) con éxito!` });
        if (csvRecipients.length === 0) setFormData({ ...formData, toEmail: '' });
      }
    } catch (error: any) {
      finalStatus = 'error';
      errorMessage = error.message;
      setStatus({ type: 'error', message: `Error tras enviar ${sentCount} mails: ${error.message}` });
    } finally {
      setIsSending(false);
      // Save log entry
      await logEmailOperation({
        fromEmail: formData.fromEmail,
        templateName: selectedTemplate.name,
        count: sentCount,
        status: finalStatus,
        error: errorMessage || undefined,
        userEmail: auth.currentUser?.email || 'unknown'
      });
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 max-w-6xl mx-auto">
      <div className="lg:col-span-6 space-y-6">
        <form onSubmit={handleSubmit} className="bg-white rounded-[2rem] shadow-xl shadow-slate-200/50 border border-slate-200 overflow-hidden transition-all">
          <div className="bg-indigo-600 px-8 py-6 text-white relative overflow-hidden">
             <div className="absolute top-0 right-0 w-24 h-24 bg-white/10 rounded-full -mr-8 -mt-8"></div>
            <h2 className="text-xl font-black flex items-center">
              <i className="fas fa-paper-plane mr-3"></i>
              Componer Envío
            </h2>
          </div>

          <div className="p-8 space-y-6">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nombre Remitente</label>
                <input
                  type="text"
                  required
                  value={formData.fromName}
                  onChange={(e) => setFormData({ ...formData, fromName: e.target.value })}
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-bold"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Email Remitente</label>
                <input
                  type="email"
                  required
                  value={formData.fromEmail}
                  onChange={(e) => setFormData({ ...formData, fromEmail: e.target.value })}
                  className={`w-full px-4 py-3 border rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-bold ${
                    !validateEmail(formData.fromEmail) ? 'border-rose-400 bg-rose-50' : 'bg-slate-50 border-slate-200'
                  }`}
                />
              </div>
            </div>

            <div className="space-y-3">
              <div className="flex justify-between items-center px-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Destinatario(s)</label>
                <button 
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="text-[10px] font-black text-indigo-600 hover:text-indigo-700 uppercase tracking-widest bg-indigo-50 px-3 py-1 rounded-full transition-all"
                >
                  <i className="fas fa-file-csv mr-1"></i> Subir CSV
                </button>
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  onChange={handleFileUpload} 
                  accept=".csv" 
                  className="hidden" 
                />
              </div>

              {csvRecipients.length > 0 ? (
                <div className="p-4 bg-indigo-50 border border-indigo-100 rounded-2xl space-y-3">
                  <div className="flex justify-between items-center">
                    <span className="text-xs font-bold text-indigo-700 italic">
                      {csvRecipients.length} correos cargados
                    </span>
                    <button onClick={clearCsv} className="text-rose-500 hover:text-rose-700 text-xs font-bold uppercase tracking-tighter" type="button">Limpiar</button>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[9px] font-black text-indigo-300 uppercase">Seleccionar Columna (Hoja)</label>
                    <select 
                      value={selectedColumn}
                      onChange={(e) => onColumnChange(e.target.value)}
                      className="w-full px-3 py-2 bg-white border border-indigo-200 rounded-xl text-xs font-bold text-indigo-800 outline-none"
                    >
                      {csvHeaders.map(h => <option key={h} value={h}>{h}</option>)}
                    </select>
                  </div>
                </div>
              ) : (
                <input
                  type="email"
                  required
                  value={formData.toEmail}
                  onChange={(e) => setFormData({ ...formData, toEmail: e.target.value })}
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-bold"
                  placeholder="ejemplo@correo.com"
                />
              )}
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Plantilla SendGrid</label>
              <select
                value={formData.templateId}
                onChange={(e) => setFormData({ ...formData, templateId: e.target.value })}
                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-bold text-slate-700 appearance-none cursor-pointer"
              >
                {TEMPLATES.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
              </select>
            </div>

            {status.message && (
              <div className={`p-4 rounded-2xl flex items-center space-x-3 ${status.type === 'success' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' : 'bg-rose-50 text-rose-700 border border-rose-100'}`}>
                <i className={`fas ${status.type === 'success' ? 'fa-check-circle' : 'fa-triangle-exclamation'} text-lg`}></i>
                <span className="text-xs font-bold tracking-tight">{status.message}</span>
              </div>
            )}

            <div className="flex gap-2">
              <button
                type="submit"
                disabled={isSending}
