// api/get-templates.ts
export default async function handler(req: any, res: any) {
  const apiKey = process.env.SENDGRID_API_KEY;

  if (!apiKey) {
    return res.status(500).json({ error: 'SendGrid API key not configured on server.' });
  }

  try {
    const response = await fetch('https://api.sendgrid.com/v3/templates?generations=dynamic', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
    });

    const data = await response.json();

    if (!response.ok) {
      throw new Error(data.errors?.[0]?.message || 'Failed to fetch templates');
    }

    // Mapeamos solo lo necesario para el dropdown
    const templates = data.templates.map((t: any) => ({
      id: t.id,
      name: t.name,
      updated_at: t.updated_at
    }));

    return res.status(200).json(templates);
  } catch (error: any) {
    console.error('Error fetching templates:', error);
    return res.status(500).json({ error: 'Error fetching templates from SendGrid' });
  }
}

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { EmailFormData } from '../types';
import { sendEmailViaSendGrid } from '../services/sendgridService';
import { logEmailOperation, auth } from '../firebase';
import Papa from 'papaparse';

interface SendGridTemplate {
  id: string;
  name: string;
}

const EmailForm: React.FC = () => {
  const [formData, setFormData] = useState<EmailFormData>({
    fromEmail: 'info@ukuepa.com',
    fromName: 'Uk Mails Admin',
    toEmail: '',
    templateId: '',
    dynamicTemplateData: ''
  });

  const [templates, setTemplates] = useState<SendGridTemplate[]>([]);
  const [loadingTemplates, setLoadingTemplates] = useState(true);

  // CSV States
  const [csvRecipients, setCsvRecipients] = useState<string[]>([]);
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [rawCsvData, setRawCsvData] = useState<any[]>([]);
  const [selectedColumn, setSelectedColumn] = useState('');

  const [isSending, setIsSending] = useState(false);
  const [cancelRequest, setCancelRequest] = useState(false);
  const [status, setStatus] = useState<{ type: 'success' | 'error' | ''; message: string }>({ type: '', message: '' });

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Cargar plantillas de SendGrid al iniciar
  useEffect(() => {
    const fetchTemplates = async () => {
      try {
        const response = await fetch('/api/get-templates');
        const data = await response.json();
        if (Array.isArray(data)) {
          setTemplates(data);
          if (data.length > 0) {
            setFormData(prev => ({ ...prev, templateId: data[0].id }));
          }
        } else {
          console.error("No se pudieron cargar las plantillas", data);
        }
      } catch (err) {
        console.error("Error al cargar templates:", err);
      } finally {
        setLoadingTemplates(false);
      }
    };

    fetchTemplates();
  }, []);

  const selectedTemplate = useMemo(() => 
    templates.find(t => t.id === formData.templateId) || { name: 'Selecciona una plantilla', id: '' }
  , [formData.templateId, templates]);

  const validateEmail = (email: string) => email.toLowerCase().endsWith('@ukuepa.com');

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setRawCsvData(results.data);
          setSelectedColumn(headers[0]);
          updateRecipients(results.data, headers[0]);
        }
      },
      error: (error) => {
        setStatus({ type: 'error', message: 'Error al procesar CSV: ' + error.message });
      }
    });
  };

  const updateRecipients = (data: any[], column: string) => {
    const emails = data.map(row => row[column]).filter(email => email && email.includes('@'));
    setCsvRecipients(emails);
    if (emails.length > 0) {
      setFormData(prev => ({ ...prev, toEmail: emails[0] }));
    }
  };

  const onColumnChange = (column: string) => {
    setSelectedColumn(column);
    updateRecipients(rawCsvData, column);
  };

  const clearCsv = () => {
    setCsvRecipients([]);
    setCsvHeaders([]);
    setRawCsvData([]);
    setSelectedColumn('');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateEmail(formData.fromEmail)) {
      setStatus({ type: 'error', message: 'El remitente debe ser @ukuepa.com' });
      return;
    }
    if (!formData.templateId) {
      setStatus({ type: 'error', message: 'Debes seleccionar una plantilla' });
      return;
    }

    setIsSending(true);
    setCancelRequest(false);
    setStatus({ type: '', message: '' });

    const targets = csvRecipients.length > 0 ? csvRecipients : [formData.toEmail];
    let sentCount = 0;
    let finalStatus: 'success' | 'error' | 'cancelled' = 'success';
    let errorMessage = '';

    try {
      for (const email of targets) {
        if (cancelRequest) {
          finalStatus = 'cancelled';
          break;
        }
        await sendEmailViaSendGrid({ ...formData, toEmail: email });
        sentCount++;
      }

      if (finalStatus === 'cancelled') {
        setStatus({ type: 'error', message: `Envío cancelado. Se enviaron ${sentCount} de ${targets.length}.` });
      } else {
        setStatus({ type: 'success', message: `¡${sentCount} mail(s) enviado(s) con éxito!` });
        if (csvRecipients.length === 0) setFormData({ ...formData, toEmail: '' });
      }
    } catch (error: any) {
      finalStatus = 'error';
      errorMessage = error.message;
      setStatus({ type: 'error', message: `Error tras enviar ${sentCount} mails: ${error.message}` });
    } finally {
      setIsSending(false);
      await logEmailOperation({
        fromEmail: formData.fromEmail,
        templateName: selectedTemplate.name,
        count: sentCount,
        status: finalStatus,
        error: errorMessage || undefined,
        userEmail: auth.currentUser?.email || 'unknown'
      });
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 max-w-6xl mx-auto">
      <div className="lg:col-span-6 space-y-6">
        <form onSubmit={handleSubmit} className="bg-white rounded-[2rem] shadow-xl shadow-slate-200/50 border border-slate-200 overflow-hidden transition-all">
          <div className="bg-indigo-600 px-8 py-6 text-white relative overflow-hidden">
             <div className="absolute top-0 right-0 w-24 h-24 bg-white/10 rounded-full -mr-8 -mt-8"></div>
            <h2 className="text-xl font-black flex items-center">
              <i className="fas fa-paper-plane mr-3"></i>
