                />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Email Remitente</label>
                <input
                  type="email"
                  required
                  value={formData.fromEmail}
                  onChange={(e) => setFormData({ ...formData, fromEmail: e.target.value })}
                  className={`w-full px-4 py-3 border rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-bold ${
                    !validateEmail(formData.fromEmail) ? 'border-rose-400 bg-rose-50' : 'bg-slate-50 border-slate-200'
                  }`}
                />
              </div>
            </div>

            <div className="space-y-3">
              <div className="flex justify-between items-center px-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Destinatario(s)</label>
                <button 
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="text-[10px] font-black text-indigo-600 hover:text-indigo-700 uppercase tracking-widest bg-indigo-50 px-3 py-1 rounded-full transition-all"
                >
                  <i className="fas fa-file-csv mr-1"></i> Subir CSV
                </button>
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  onChange={handleFileUpload} 
                  accept=".csv" 
                  className="hidden" 
                />
              </div>

              {csvRecipients.length > 0 ? (
                <div className="p-4 bg-indigo-50 border border-indigo-100 rounded-2xl space-y-3">
                  <div className="flex justify-between items-center">
                    <span className="text-xs font-bold text-indigo-700 italic">
                      {csvRecipients.length} correos cargados
                    </span>
                    <button onClick={clearCsv} className="text-rose-500 hover:text-rose-700 text-xs font-bold uppercase tracking-tighter" type="button">Limpiar</button>
