export const isUserAuthorized = async (email: string): Promise<boolean> => {
  if (email.toLowerCase() === ADMIN_EMAIL.toLowerCase()) return true;
  const docRef = doc(db, COLLECTION_NAME, email.toLowerCase());
  const docSnap = await getDoc(docRef);
  return docSnap.exists();
};

export const addAuthorizedUser = async (email: string, adminEmail: string) => {
  const emailLower = email.toLowerCase();
  await setDoc(doc(db, COLLECTION_NAME, emailLower), {
    email: emailLower,
    addedAt: Date.now(),
    addedBy: adminEmail
  });
};

export const removeAuthorizedUser = async (email: string) => {
  await deleteDoc(doc(db, COLLECTION_NAME, email.toLowerCase()));
};

export const logEmailOperation = async (logData: {
  fromEmail: string;
  templateName: string;
  count: number;
  status: 'success' | 'error' | 'cancelled';
  error?: string;
  userEmail: string;
}) => {
  try {
    const dataToSave = {
      ...logData,
      timestamp: serverTimestamp(),
    };
    const docRef = await addDoc(collection(db, LOGS_COLLECTION), dataToSave);
    console.log("Log guardado exitosamente con ID:", docRef.id);
    return docRef.id;
  } catch (e) {
    console.error("Error crítico al guardar log en Firebase:", e);
    // Intentar un guardado de emergencia con timestamp local si falla el del servidor
    try {
        await addDoc(collection(db, LOGS_COLLECTION), {
            ...logData,
            timestamp: Date.now(),
            backupSave: true
        });
    } catch (innerError) {
        console.error("Fallo total de persistencia:", innerError);
    }
  }
};

import { EmailFormData } from '../types';

export const sendEmailViaSendGrid = async (data: EmailFormData) => {
  try {
    const response = await fetch('/api/send-email', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(data),
    });

    // Leemos primero como texto para evitar el error de JSON vacío
    const responseText = await response.text();
    let result;

    try {
      result = responseText ? JSON.parse(responseText) : {};
    } catch (e) {
      result = { error: 'Error al procesar respuesta del servidor', details: responseText };
    }

    if (!response.ok) {
      throw new Error(result.error || result.details || `Error del servidor (${response.status})`);
    }

    return result;
  } catch (error: any) {
    console.error('Error en Servicio SendGrid:', error);
    throw error;
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../firebase';
