const EmailLogs: React.FC = () => {
  const [logs, setLogs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Escuchamos en tiempo real con ordenamiento por timestamp
    const q = query(
      collection(db, 'email_logs'),
      orderBy('timestamp', 'desc'),
      limit(100)
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const logList = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          id: doc.id,
          ...data,
          // Normalizamos el timestamp para que sea legible independientemente de si es objeto o número
          formattedDate: data.timestamp?.toDate 
            ? data.timestamp.toDate() 
            : data.timestamp 
              ? new Date(data.timestamp) 
              : new Date()
        };
      });
      console.log("Logs recibidos:", logList.length);
      setLogs(logList);
      setLoading(false);
    }, (error) => {
      console.error("Error en onSnapshot de logs:", error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const stats = useMemo(() => {
    return logs.reduce((acc, log) => {
      const count = Number(log.count) || 0;
      acc.total += count;
      if (log.status === 'success') acc.success += count;
      if (log.status === 'error') acc.error += 1;
      if (log.status === 'cancelled') acc.cancelled += 1;
      return acc;
