import Papa from 'papaparse';

interface SendGridTemplate {
  id: string;
  name: string;
}

const EmailForm: React.FC = () => {
  const [formData, setFormData] = useState<EmailFormData>({
    fromEmail: 'info@ukuepa.com',
    fromName: 'Uk Mails Admin',
    toEmail: '',
    templateId: '',
    dynamicTemplateData: ''
  });

  const [templates, setTemplates] = useState<SendGridTemplate[]>([]);
  const [loadingTemplates, setLoadingTemplates] = useState(true);
  const [csvRecipients, setCsvRecipients] = useState<string[]>([]);
  const [csvHeaders, setCsvHeaders] = useState<string[]>([]);
  const [rawCsvData, setRawCsvData] = useState<any[]>([]);
  const [selectedColumn, setSelectedColumn] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [cancelRequest, setCancelRequest] = useState(false);
  const [status, setStatus] = useState<{ type: 'success' | 'error' | ''; message: string }>({ type: '', message: '' });

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const fetchTemplates = async () => {
      try {
        const response = await fetch('/api/get-templates');
        const data = await response.json();
        if (Array.isArray(data)) {
          setTemplates(data);
          if (data.length > 0) {
            setFormData(prev => ({ ...prev, templateId: data[0].id }));
          }
        }
      } catch (err) {
        console.error("Error al cargar templates:", err);
      } finally {
        setLoadingTemplates(false);
      }
    };
    fetchTemplates();
  }, []);

  const selectedTemplate = useMemo(() => 
    templates.find(t => t.id === formData.templateId) || { name: 'Plantilla UK', id: formData.templateId }
  , [formData.templateId, templates]);

  const validateEmail = (email: string) => email && email.toLowerCase().endsWith('@ukuepa.com');

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          setCsvHeaders(headers);
          setRawCsvData(results.data);
          setSelectedColumn(headers[0]);
          updateRecipients(results.data, headers[0]);
        }
      },
    });
  };

  const updateRecipients = (data: any[], column: string) => {
    const emails = data.map(row => row[column]).filter(email => email && email.includes('@'));
    setCsvRecipients(emails);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateEmail(formData.fromEmail)) {
      setStatus({ type: 'error', message: 'Remitente debe ser @ukuepa.com' });
      return;
    }

    const targets = csvRecipients.length > 0 ? csvRecipients : [formData.toEmail].filter(em => em.trim() !== '');
    if (targets.length === 0) {
      setStatus({ type: 'error', message: 'Ingresa un destinatario válido' });
      return;
    }

    setIsSending(true);
    setCancelRequest(false);
    setStatus({ type: '', message: '' });

    let sentCount = 0;
    let finalStatus: 'success' | 'error' | 'cancelled' = 'success';
    let errorMessage = '';

    try {
      for (const email of targets) {
        if (cancelRequest) {
          finalStatus = 'cancelled';
          break;
        }
        await sendEmailViaSendGrid({ ...formData, toEmail: email.trim() });
        sentCount++;
      }

      if (finalStatus !== 'cancelled') {
        setStatus({ type: 'success', message: `¡${sentCount} mail(s) enviado(s) con éxito!` });
      } else {
        setStatus({ type: 'error', message: `Operación cancelada. Enviados: ${sentCount}` });
      }
    } catch (error: any) {
      finalStatus = 'error';
      errorMessage = error.message || 'Error desconocido en el envío';
      setStatus({ type: 'error', message: errorMessage });
    } finally {
      // IMPORTANTE: Primero logueamos, LUEGO quitamos el estado de carga
      console.log("Registrando operación en historial...");
      await logEmailOperation({
        fromEmail: formData.fromEmail,
        templateName: selectedTemplate.name || 'Plantilla Desconocida',
        count: sentCount,
        status: finalStatus,
        error: errorMessage || undefined,
        userEmail: auth.currentUser?.email || 'operador@ukuepa.com'
      });
      setIsSending(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 max-w-6xl mx-auto">
      <div className="lg:col-span-6 space-y-6">
        <form onSubmit={handleSubmit} className="bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl border border-slate-200 dark:border-slate-800 overflow-hidden">
          <div className="bg-ukblue px-10 py-8 text-white relative overflow-hidden">
            <h2 className="text-xl font-black flex items-center tracking-tighter">
              <i className="fas fa-magic mr-3 text-indigo-400"></i>
              Configurar Envío
            </h2>
          </div>

          <div className="p-10 space-y-8">
            <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest ml-1">Nombre Display</label>
                  <input
                    type="text"
                    required
                    value={formData.fromName}
                    onChange={(e) => setFormData({ ...formData, fromName: e.target.value })}
                    className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl focus:ring-2 focus:ring-ukblue dark:focus:ring-indigo-500 outline-none text-sm font-bold dark:text-white"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest ml-1">Email Remitente (@ukuepa.com)</label>
                  <input
                    type="email"
                    required
                    value={formData.fromEmail}
                    onChange={(e) => setFormData({ ...formData, fromEmail: e.target.value })}
                    className={`w-full px-5 py-4 border rounded-2xl outline-none text-sm font-bold dark:text-white ${
                      !validateEmail(formData.fromEmail) ? 'border-rose-400 bg-rose-50 dark:bg-rose-950/20' : 'bg-slate-50 dark:bg-slate-800 border-slate-200 dark:border-slate-700'
                    }`}
                  />
                </div>
            </div>

            <div className="space-y-3">
              <div className="flex justify-between items-center px-1">
                <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Destinatarios</label>
                <button 
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="text-[9px] font-black text-white uppercase tracking-widest bg-ukblue dark:bg-indigo-600 px-4 py-2 rounded-xl"
                >
                  <i className="fas fa-file-csv mr-2"></i> Subir CSV
                </button>
                <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept=".csv" className="hidden" />
              </div>

              {csvRecipients.length > 0 ? (
                <div className="p-6 bg-indigo-50 dark:bg-indigo-950/20 border border-indigo-100 dark:border-indigo-900/50 rounded-2xl">
                  <div className="flex justify-between items-center">
                    <span className="text-xs font-black text-ukblue dark:text-indigo-300">
                      <i className="fas fa-users mr-2"></i> {csvRecipients.length} destinatarios listos
                    </span>
                    <button type="button" onClick={() => setCsvRecipients([])} className="text-rose-500 font-black text-[10px] uppercase">Quitar</button>
                  </div>
                </div>
              ) : (
                <input
                  type="email"
                  value={formData.toEmail}
                  onChange={(e) => setFormData({ ...formData, toEmail: e.target.value })}
                  className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl outline-none text-sm font-bold dark:text-white"
                  placeholder="ejemplo@ukuepa.com"
                />
              )}
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest ml-1">Plantilla SendGrid</label>
              <select
                value={formData.templateId}
                onChange={(e) => setFormData({ ...formData, templateId: e.target.value })}
                disabled={loadingTemplates}
                className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-sm font-black text-slate-700 dark:text-slate-200"
              >
                {loadingTemplates ? (
                  <option>Cargando plantillas...</option>
                ) : templates.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
              </select>
            </div>

            {status.message && (
              <div className={`p-5 rounded-2xl flex items-center space-x-4 ${status.type === 'success' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100 dark:bg-emerald-950/20' : 'bg-rose-50 text-rose-700 border border-rose-100 dark:bg-rose-950/20'}`}>
                <i className={`fas ${status.type === 'success' ? 'fa-check-circle' : 'fa-times-circle'} text-xl`}></i>
                <span className="text-xs font-black">{status.message}</span>
              </div>
            )}

            <div className="flex gap-3">
              <button
                type="submit"
                disabled={isSending || loadingTemplates}
                className="flex-1 py-5 bg-ukblue hover:bg-slate-800 dark:bg-indigo-600 dark:hover:bg-indigo-700 text-white rounded-2xl font-black text-sm uppercase tracking-widest transition-all flex items-center justify-center space-x-4 disabled:opacity-50"
              >
                {isSending ? (
                  <><i className="fas fa-circle-notch fa-spin"></i><span>Enviando Batch...</span></>
                ) : (
                  <><i className="fas fa-paper-plane"></i><span>{csvRecipients.length > 0 ? `Enviar a ${csvRecipients.length} contactos` : 'Enviar Correo'}</span></>
                )}
              </button>

              {isSending && (
                <button
                  type="button"
                  onClick={() => setCancelRequest(true)}
                  className="px-8 bg-rose-100 text-rose-600 rounded-2xl font-black text-xs hover:bg-rose-200"
                >
                  PARAR
                </button>
              )}
            </div>
          </div>
        </form>
      </div>

      <div className="lg:col-span-6 hidden lg:block">
        <div className="bg-slate-100 dark:bg-slate-800 rounded-[3rem] border-8 border-white dark:border-slate-900 shadow-2xl p-8 min-h-[600px] flex flex-col">
          <div className="flex-1 bg-white dark:bg-slate-950 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 p-12 flex flex-col items-center justify-center text-center space-y-6">
             <div className="w-20 h-20 bg-ukblue/5 dark:bg-white/5 rounded-[2rem] flex items-center justify-center">
