// api/send-email.ts
import sgMail from '@sendgrid/mail';

export default async function handler(req: any, res: any) {
  // Siempre respondemos con JSON
  res.setHeader('Content-Type', 'application/json');

  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed', success: false });
  }

  const apiKey = process.env.SENDGRID_API_KEY;
  if (!apiKey) {
    console.error('API KEY faltante en el servidor');
    return res.status(500).json({ error: 'Configuración de servidor incompleta (SendGrid Key)', success: false });
  }

  try {
    sgMail.setApiKey(apiKey);

    const { toEmail, fromEmail, fromName, templateId, dynamicTemplateData } = req.body;

    if (!toEmail || !templateId) {
      return res.status(400).json({ error: 'Destinatario y plantilla son requeridos', success: false });
    }

    const msg = {
      to: toEmail,
      from: {
        email: fromEmail || 'info@ukuepa.com',
        name: fromName || 'Uk Mails'
      },
      templateId: templateId,
      dynamicTemplateData: dynamicTemplateData || {},
    };

    const [response] = await sgMail.send(msg);

    // Si llegamos aquí es un éxito de SendGrid (Status 2xx)
    return res.status(200).json({ 
      success: true, 
      message: 'Email procesado por SendGrid',
      statusCode: response.statusCode 
    });
  } catch (error: any) {
    const errorBody = error.response?.body || {};
    const errorMessage = errorBody.errors?.[0]?.message || error.message || 'Error desconocido al contactar SendGrid';

    console.error('SendGrid API Error:', errorMessage);

    return res.status(500).json({ 
      error: 'Error en el proveedor de correos', 
      details: errorMessage,
      success: false 
    });
  }
}

import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../firebase';
import { collection, onSnapshot, query, orderBy, limit } from 'firebase/firestore';

const EmailLogs: React.FC = () => {
  const [logs, setLogs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const q = query(
      collection(db, 'email_logs'),
      orderBy('timestamp', 'desc'),
      limit(100)
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const logList = snapshot.docs.map(doc => {
        const data = doc.data();
        let finalDate = new Date();

        // Manejamos cualquier tipo de formato de fecha guardado (Timestamp o Number)
        if (data.timestamp) {
          if (typeof data.timestamp.toDate === 'function') {
            finalDate = data.timestamp.toDate();
          } else if (typeof data.timestamp === 'number') {
            finalDate = new Date(data.timestamp);
          } else {
            finalDate = new Date(data.timestamp);
          }
        }

        return {
          id: doc.id,
          ...data,
          formattedDate: finalDate
        };
      });
      setLogs(logList);
      setLoading(false);
    }, (error) => {
      console.error("Error cargando historial:", error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const stats = useMemo(() => {
    return logs.reduce((acc, log) => {
      const count = Number(log.count) || 0;
      acc.total += count;
      if (log.status === 'success') acc.success += count;
      if (log.status === 'error') acc.error += 1;
      if (log.status === 'cancelled') acc.cancelled += 1;
      return acc;
    }, { total: 0, success: 0, error: 0, cancelled: 0 });
  }, [logs]);

  return (
    <div className="max-w-6xl mx-auto space-y-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 dark:text-white tracking-tighter">Dashboard de Envíos</h2>
          <p className="text-xs font-bold text-indigo-500 uppercase tracking-widest mt-1">Sincronización de registros histórica</p>
        </div>
        <div className="px-4 py-2 bg-emerald-50 dark:bg-emerald-950/20 border border-emerald-100 dark:border-emerald-900/50 rounded-2xl text-[10px] font-black text-emerald-600 uppercase tracking-widest flex items-center">
            <i className="fas fa-database mr-2"></i> Cloud Sync Online
        </div>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total Enviados</p>
           <h3 className="text-3xl font-black text-ukblue dark:text-white mt-1">{stats.total}</h3>
        </div>
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Exitosos</p>
           <h3 className="text-3xl font-black text-emerald-600 mt-1">{stats.success}</h3>
        </div>
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Errores</p>
           <h3 className="text-3xl font-black text-rose-600 mt-1">{stats.error}</h3>
        </div>
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Cancelados</p>
