import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../firebase';
import { collection, onSnapshot, query, orderBy, limit } from 'firebase/firestore';

const EmailLogs: React.FC = () => {
  const [logs, setLogs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Escuchamos por timestamp descendiente para que lo último aparezca arriba
    const q = query(
      collection(db, 'email_logs'),
      orderBy('timestamp', 'desc'),
      limit(100)
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const logList = snapshot.docs.map(doc => {
        const data = doc.data();
        let finalDate = new Date();

        if (data.timestamp) {
          if (typeof data.timestamp.toDate === 'function') {
            finalDate = data.timestamp.toDate();
          } else {
            finalDate = new Date(data.timestamp);
          }
        } else if (data.createdAt) {
          finalDate = new Date(data.createdAt);
        }

        return {
          id: doc.id,
          ...data,
          formattedDate: finalDate
        };
      });
      setLogs(logList);
      setLoading(false);
    }, (error) => {
      console.error("Error cargando historial de Firestore:", error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const stats = useMemo(() => {
    return logs.reduce((acc, log) => {
      const count = Number(log.count) || 0;
      acc.total += count;
      if (log.status === 'success') acc.success += count;
      if (log.status === 'error') acc.error += count; // Corregido: Suma el count, no 1
      if (log.status === 'cancelled') acc.cancelled += count; // Corregido: Suma el count, no 1
      return acc;
    }, { total: 0, success: 0, error: 0, cancelled: 0 });
  }, [logs]);

  return (
    <div className="max-w-6xl mx-auto space-y-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 dark:text-white tracking-tighter">Dashboard de Envíos</h2>
          <p className="text-xs font-bold text-indigo-500 uppercase tracking-widest mt-1">Registros guardados en Cloud Firestore</p>
        </div>
        <div className="px-4 py-2 bg-emerald-50 dark:bg-emerald-950/20 border border-emerald-100 dark:border-emerald-900/50 rounded-2xl text-[10px] font-black text-emerald-600 uppercase tracking-widest flex items-center">
            <i className="fas fa-cloud-upload-alt mr-2"></i> Historial Sincronizado
        </div>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total Intentados</p>
           <h3 className="text-3xl font-black text-ukblue dark:text-white mt-1">{stats.total.toLocaleString()}</h3>
        </div>
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Exitosos</p>
           <h3 className="text-3xl font-black text-emerald-600 mt-1">{stats.success.toLocaleString()}</h3>
        </div>
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Fallas de Envío</p>
           <h3 className="text-3xl font-black text-rose-600 mt-1">{stats.error.toLocaleString()}</h3>
        </div>
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Cancelados</p>
           <h3 className="text-3xl font-black text-amber-600 mt-1">{stats.cancelled.toLocaleString()}</h3>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-slate-100 dark:divide-slate-800">
            <thead className="bg-slate-50 dark:bg-slate-800/50">
              <tr>
                <th className="px-8 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">Fecha / Hora</th>
                <th className="px-8 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">Plantilla</th>
                <th className="px-8 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">Volumen</th>
                <th className="px-8 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">Operador</th>
                <th className="px-8 py-5 text-center text-[10px] font-black text-slate-400 uppercase tracking-widest">Estado</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
              {loading ? (
                <tr><td colSpan={5} className="py-20 text-center font-bold text-slate-400">Sincronizando con Cloud...</td></tr>
              ) : logs.length === 0 ? (
                <tr><td colSpan={5} className="py-20 text-center font-bold text-slate-400 italic">Sin actividad registrada en la base de datos</td></tr>
              ) : (
                logs.map((log) => (
                  <tr key={log.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors">
                    <td className="px-8 py-6">
                      <div className="text-xs font-black text-slate-700 dark:text-slate-200">{log.formattedDate.toLocaleDateString()}</div>
                      <div className="text-[10px] text-slate-400 font-bold">{log.formattedDate.toLocaleTimeString()}</div>
                    </td>
                    <td className="px-8 py-6">
                      <span className="text-sm font-black text-ukblue dark:text-indigo-300">{log.templateName}</span>
                      <div className="text-[9px] font-bold text-slate-400">{log.templateId}</div>
                    </td>
                    <td className="px-8 py-6">
                      <span className="text-xs font-black text-indigo-600 bg-indigo-50/50 dark:bg-indigo-950/20 px-3 py-1 rounded-lg">
                        {log.count} mails
                      </span>
                    </td>
                    <td className="px-8 py-6 text-[10px] font-black text-slate-500 uppercase">
                      {log.userEmail ? log.userEmail.split('@')[0] : 'admin'}
                    </td>
                    <td className="px-8 py-6 text-center">
                      <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                        log.status === 'success' ? 'bg-emerald-50 text-emerald-700 border-emerald-100 dark:bg-emerald-950/30 dark:text-emerald-400' :
                        log.status === 'cancelled' ? 'bg-amber-50 text-amber-700 border-amber-100 dark:bg-amber-950/30 dark:text-amber-400' :
                        'bg-rose-50 text-rose-700 border-rose-100 dark:bg-rose-950/30 dark:text-rose-400'
                      }`}>
                        {log.status === 'success' ? 'Exitoso' : log.status === 'cancelled' ? 'Parado' : 'Error'}
                      </span>
                      {log.error && <div className="text-[8px] text-rose-400 mt-1 max-w-[120px] truncate mx-auto">{log.error}</div>}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default EmailLogs;

