import React, { useState, useMemo, useRef, useEffect } from 'react';
import { EmailFormData } from '../types';
import { sendEmailViaSendGrid } from '../services/sendgridService';
import { saveEmailLog } from '../firebase';
import Papa from 'papaparse';

interface SendGridTemplate {
  id: string;
  name: string;
}

const EmailForm: React.FC = () => {
  const [formData, setFormData] = useState<EmailFormData>({
    fromEmail: 'info@ukuepa.com',
    fromName: 'Uk Mails Admin',
    toEmail: '',
    templateId: '',
    dynamicTemplateData: ''
  });

  const [templates, setTemplates] = useState<SendGridTemplate[]>([]);
  const [loadingTemplates, setLoadingTemplates] = useState(true);
  const [csvRecipients, setCsvRecipients] = useState<string[]>([]);
  const [isSending, setIsSending] = useState(false);
  const [cancelRequest, setCancelRequest] = useState(false);
  const [status, setStatus] = useState<{ type: 'success' | 'error' | ''; message: string }>({ type: '', message: '' });

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const fetchTemplates = async () => {
      try {
        const response = await fetch('/api/get-templates');
        if (!response.ok) throw new Error("No se pudieron cargar plantillas");
        const data = await response.json();
        if (Array.isArray(data)) {
          setTemplates(data);
          if (data.length > 0) {
            setFormData(prev => ({ ...prev, templateId: data[0].id }));
          }
        }
      } catch (err) {
        console.error("Error al cargar templates:", err);
      } finally {
        setLoadingTemplates(false);
      }
    };
    fetchTemplates();
  }, []);

  const selectedTemplate = useMemo(() => 
    templates.find(t => t.id === formData.templateId) || { name: 'Cargando plantilla...', id: formData.templateId }
  , [formData.templateId, templates]);

  const validateEmail = (email: string) => email && email.toLowerCase().endsWith('@ukuepa.com');

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        if (results.data.length > 0) {
          const headers = Object.keys(results.data[0]);
          const emailCol = headers.find(h => h.toLowerCase().includes('email') || h.toLowerCase().includes('correo')) || headers[0];
          const emails = results.data.map((row: any) => row[emailCol]).filter(email => email && email.includes('@'));
          setCsvRecipients(emails);
        }
      },
    });
  };

  const handleSendEmails = async (e: React.FormEvent) => {
    e.preventDefault();

    const targets = csvRecipients.length > 0 ? csvRecipients : [formData.toEmail].filter(em => em.trim() !== '');
    if (targets.length === 0) {
      setStatus({ type: 'error', message: 'No hay destinatarios válidos' });
      return;
    }

    setIsSending(true);
    setCancelRequest(false);
    setStatus({ type: '', message: '' });

    let successCount = 0;
    // Widening the type and using a variable that won't be narrowed to avoid the non-overlap error
    let finalStatus: 'success' | 'error' | 'cancelled' = 'success';
    let errorMessage = '';

    try {
      for (const email of targets) {
        if (cancelRequest) {
          finalStatus = 'cancelled';
          break;
        }
        try {
          await sendEmailViaSendGrid({ ...formData, toEmail: email.trim() });
          successCount++;
        } catch (mailErr: any) {
          if (targets.length === 1) {
            finalStatus = 'error';
            errorMessage = mailErr.message;
            throw mailErr;
          }
        }
      }

      // Fix: Simplified check to avoid non-overlapping type error when finalStatus is narrowed.
      // At this point in the try block, finalStatus can only be 'success' or 'cancelled' 
      // because the 'error' state leads to an exception which is handled in the outer catch.
      if (finalStatus === 'success') {
        setStatus({ type: 'success', message: `¡Proceso completado! ${successCount} correos enviados.` });
      } else if (finalStatus === 'cancelled') {
        setStatus({ type: 'error', message: `Envío cancelado. Se enviaron ${successCount} correos.` });
      }
    } catch (error: any) {
      finalStatus = 'error';
      errorMessage = error.message;
      setStatus({ type: 'error', message: `Error: ${errorMessage}` });
    } finally {
      // GUARDAR EN FIREBASE (AWAIT CRUCIAL)
      await saveEmailLog({
        templateName: selectedTemplate.name,
        templateId: formData.templateId,
        count: successCount > 0 ? successCount : (finalStatus === 'error' ? targets.length : 0),
        status: finalStatus,
        fromEmail: formData.fromEmail,
        error: errorMessage || undefined
      });
      setIsSending(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 max-w-6xl mx-auto">
      {/* Formulario a la izquierda */}
      <div className="lg:col-span-6 space-y-6">
        <form onSubmit={handleSendEmails} className="bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl border border-slate-200 dark:border-slate-800 overflow-hidden">
          <div className="bg-ukblue px-10 py-8 text-white relative overflow-hidden">
            <h2 className="text-xl font-black flex items-center tracking-tighter">
              <i className="fas fa-magic mr-3 text-indigo-400"></i>
              Configurar Envío
            </h2>
          </div>

          <div className="p-10 space-y-8">
            <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest ml-1">Email Remitente (@ukuepa.com)</label>
                  <input
                    type="email"
                    required
                    value={formData.fromEmail}
                    onChange={(e) => setFormData({ ...formData, fromEmail: e.target.value })}
                    className={`w-full px-5 py-4 border rounded-2xl outline-none text-sm font-bold dark:text-white ${
                      !validateEmail(formData.fromEmail) ? 'border-rose-400 bg-rose-50 dark:bg-rose-950/20' : 'bg-slate-50 dark:bg-slate-800 border-slate-200 dark:border-slate-700'
                    }`}
                  />
                </div>
            </div>

            <div className="space-y-3">
              <div className="flex justify-between items-center px-1">
                <label className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">Destinatarios</label>
                <button 
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="text-[9px] font-black text-white uppercase tracking-widest bg-ukblue dark:bg-indigo-600 px-4 py-2 rounded-xl"
                >
                  <i className="fas fa-file-csv mr-2"></i> CSV Masivo
                </button>
                <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept=".csv" className="hidden" />
              </div>

              {csvRecipients.length > 0 ? (
                <div className="p-6 bg-indigo-50 dark:bg-indigo-950/20 border border-indigo-100 dark:border-indigo-900/50 rounded-2xl flex justify-between items-center">
                  <span className="text-xs font-black text-ukblue dark:text-indigo-300 uppercase">
