              )}
            </div>
          </div>
        </form>
      </div>

      {/* VISTA PREVIA (DERECHA) */}
      <div className="lg:col-span-6">
        <div className="sticky top-28 space-y-6">
          <div className="bg-slate-200 dark:bg-slate-800 rounded-[3rem] p-2 shadow-inner">
